using UnityEngine;

/// <summary>
/// Abstract base class for all enemy types.
/// Provides common functionality and defines the contract for enemy behaviors.
/// </summary>
public abstract class BaseEnemy : MonoBehaviour
{
    [Header("Base Enemy Settings")]
    [Tooltip("Base movement speed of the enemy")]
    [SerializeField] protected float moveSpeed = 3f;

    [Tooltip("Damage dealt to the bird on collision")]
    [SerializeField] protected int damage = 1;

    [Tooltip("Reference to the bird transform (auto-assigned if null)")]
    [SerializeField] protected Transform birdTransform;

    [Tooltip("X position at which the enemy is destroyed")]
    [SerializeField] protected float destroyX = -15f;

    [Header("Visual Settings")]
    [SerializeField] protected SpriteRenderer spriteRenderer;

    // Events for external systems
    public System.Action<BaseEnemy> OnEnemyDestroyed;
    public System.Action<BaseEnemy> OnEnemyKilled;

    protected bool isActive = true;
    protected Vector3 initialScale;

    #region Unity Lifecycle

    protected virtual void Awake()
    {
        initialScale = transform.localScale;

        if (spriteRenderer == null)
            spriteRenderer = GetComponentInChildren<SpriteRenderer>();
    }

    protected virtual void Start()
    {
        // Auto-find bird if not assigned
        if (birdTransform == null)
        {
            var bird = FindFirstObjectByType<Bird>();
            if (bird != null)
                birdTransform = bird.transform;
        }
    }

    protected virtual void Update()
    {
        if (!isActive) return;

        // Execute enemy-specific behavior
        ExecuteBehavior();

        // Check if enemy should be destroyed (off-screen)
        CheckBounds();
    }

    protected virtual void OnTriggerEnter2D(Collider2D collision)
    {
        if (!isActive) return;

        // Check collision with bird
        if (collision.TryGetComponent<Bird>(out var bird))
        {
            OnHitBird(bird);
        }
    }

    protected virtual void OnDestroy()
    {
        OnEnemyDestroyed?.Invoke(this);
    }

    #endregion

    #region Abstract Methods

    /// <summary>
    /// Main behavior logic - must be implemented by each enemy type
    /// </summary>
    protected abstract void ExecuteBehavior();

    /// <summary>
    /// Returns the enemy type for identification
    /// </summary>
    public abstract EnemyType GetEnemyType();

    #endregion

    #region Virtual Methods

    /// <summary>
    /// Called when the enemy hits the bird
    /// </summary>
    protected virtual void OnHitBird(Bird bird)
    {
        // Default behavior: deal damage and destroy self
        for (int i = 0; i < damage; i++)
        {
            bird.GetHit();
        }

        DestroySelf();
    }

    /// <summary>
    /// Called when the enemy is killed (by player action, not bounds)
    /// </summary>
    public virtual void Kill()
    {
        if (!isActive) return;

        isActive = false;
        OnEnemyKilled?.Invoke(this);
        DestroySelf();
    }

    /// <summary>
    /// Check if enemy is out of bounds
    /// </summary>
    protected virtual void CheckBounds()
    {
        if (transform.position.x < destroyX)
        {
            DestroySelf();
        }
    }

    /// <summary>
    /// Destroy the enemy game object
    /// </summary>
    protected virtual void DestroySelf()
    {
        isActive = false;
        Destroy(gameObject);
    }

    #endregion

    #region Public Methods

    /// <summary>
    /// Initialize the enemy with runtime settings
    /// </summary>
    public virtual void Initialize(float speed, Transform bird, float destroyPosX)
    {
        moveSpeed = speed;
        birdTransform = bird;
        destroyX = destroyPosX;
        isActive = true;
    }

    /// <summary>
    /// Set the movement speed
    /// </summary>
    public void SetSpeed(float speed)
    {
        moveSpeed = speed;
    }

    /// <summary>
    /// Get the current movement speed
    /// </summary>
    public float GetSpeed()
    {
        return moveSpeed;
    }

    /// <summary>
    /// Set the damage value
    /// </summary>
    public void SetDamage(int dmg)
    {
        damage = dmg;
    }

    /// <summary>
    /// Pause/Resume enemy behavior
    /// </summary>
    public void SetActive(bool active)
    {
        isActive = active;
    }

    /// <summary>
    /// Check if enemy is currently active
    /// </summary>
    public bool IsActive()
    {
        return isActive;
    }

    #endregion

    #region Helper Methods

    /// <summary>
    /// Get distance to bird
    /// </summary>
    protected float GetDistanceToBird()
    {
        if (birdTransform == null) return float.MaxValue;
        return Vector2.Distance(transform.position, birdTransform.position);
    }

    /// <summary>
    /// Get direction to bird (normalized)
    /// </summary>
    protected Vector2 GetDirectionToBird()
    {
        if (birdTransform == null) return Vector2.left;
        return ((Vector2)(birdTransform.position - transform.position)).normalized;
    }

    #endregion
}

/// <summary>
/// Enum for identifying enemy types
/// </summary>
public enum EnemyType
{
    Normal,
    Follow,
    Explode,
    Split,
    Rotate
}

using UnityEngine;

/// <summary>
/// Normal enemy that simply moves left at a constant speed.
/// The most basic enemy type - serves as the foundation for other behaviors.
/// </summary>
public class NormalEnemy : BaseEnemy
{
    public override EnemyType GetEnemyType() => EnemyType.Normal;

    protected override void ExecuteBehavior()
    {
        // Simple left movement
        transform.Translate(Vector3.left * moveSpeed * Time.deltaTime);
    }
}

using UnityEngine;

/// <summary>
/// Enemy that follows the bird when within detection range.
/// Uses smooth interpolation for non-aggressive following behavior.
/// </summary>
public class FollowEnemy : BaseEnemy
{
    [Header("Follow Settings")]
    [Tooltip("Distance at which the enemy starts following the bird")]
    [SerializeField] private float detectionRange = 8f;

    [Tooltip("How smoothly the enemy follows (lower = smoother)")]
    [SerializeField] private float followSmoothness = 2f;

    [Tooltip("Speed multiplier when following")]
    [SerializeField] private float followSpeedMultiplier = 0.7f;

    [Tooltip("Minimum distance to maintain from bird")]
    [SerializeField] private float minDistanceFromBird = 1f;

    [Header("Base Movement")]
    [Tooltip("Continue moving left even when following")]
    [SerializeField] private bool maintainLeftMovement = true;

    [Tooltip("Base left movement speed when following")]
    [SerializeField] private float baseLeftSpeed = 1f;

    private bool isFollowing = false;
    private Vector3 velocity = Vector3.zero;

    public override EnemyType GetEnemyType() => EnemyType.Follow;

    protected override void ExecuteBehavior()
    {
        float distanceToBird = GetDistanceToBird();

        // Check if bird is within detection range
        if (distanceToBird <= detectionRange && birdTransform != null)
        {
            isFollowing = true;
            FollowBird(distanceToBird);
        }
        else
        {
            isFollowing = false;
            // Default left movement when not following
            transform.Translate(Vector3.left * moveSpeed * Time.deltaTime);
        }
    }

    private void FollowBird(float currentDistance)
    {
        if (birdTransform == null) return;

        Vector3 targetPosition = transform.position;

        // Only follow if not too close
        if (currentDistance > minDistanceFromBird)
        {
            // Calculate target position (slightly behind bird's Y position for smoother feel)
            targetPosition = new Vector3(
                transform.position.x, // Keep X, we'll handle horizontal movement separately
                birdTransform.position.y,
                transform.position.z
            );

            // Smooth follow on Y axis
            transform.position = Vector3.SmoothDamp(
                transform.position,
                targetPosition,
                ref velocity,
                1f / followSmoothness
            );
        }

        // Always move left (either base speed or full speed)
        float leftSpeed = maintainLeftMovement ? baseLeftSpeed : moveSpeed * followSpeedMultiplier;
        transform.Translate(Vector3.left * leftSpeed * Time.deltaTime);
    }

    /// <summary>
    /// Check if enemy is currently following the bird
    /// </summary>
    public bool IsFollowing()
    {
        return isFollowing;
    }

    /// <summary>
    /// Set the detection range at runtime
    /// </summary>
    public void SetDetectionRange(float range)
    {
        detectionRange = range;
    }

#if UNITY_EDITOR
    // Visualize detection range in editor
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = isFollowing ? Color.red : Color.yellow;
        Gizmos.DrawWireSphere(transform.position, detectionRange);
    }
#endif
}

using UnityEngine;

/// <summary>
/// Enemy that grows in size when approaching the bird and deals extra damage on collision.
/// Creates tension as the player sees the enemy getting bigger and more threatening.
/// </summary>
public class ExplodeEnemy : BaseEnemy
{
    [Header("Explode Settings")]
    [Tooltip("Distance at which the enemy starts growing")]
    [SerializeField] private float growStartDistance = 6f;

    [Tooltip("Maximum scale multiplier when fully grown")]
    [SerializeField] private float maxScaleMultiplier = 2f;

    [Tooltip("How fast the enemy grows")]
    [SerializeField] private float growSpeed = 2f;

    [Tooltip("Extra damage dealt when exploding (added to base damage)")]
    [SerializeField] private int explosionBonusDamage = 1;

    [Header("Visual Feedback")]
    [Tooltip("Color to tint when growing")]
    [SerializeField] private Color growColor = new Color(1f, 0.5f, 0.5f, 1f);

    [Tooltip("Enable pulsing effect when fully grown")]
    [SerializeField] private bool enablePulse = true;

    [Tooltip("Pulse speed when fully grown")]
    [SerializeField] private float pulseSpeed = 5f;

    [Tooltip("Pulse intensity (scale variation)")]
    [SerializeField] private float pulseIntensity = 0.1f;

    private float currentScaleMultiplier = 1f;
    private Color originalColor;
    private bool isGrowing = false;
    private bool isFullyGrown = false;

    public override EnemyType GetEnemyType() => EnemyType.Explode;

    protected override void Awake()
    {
        base.Awake();

        if (spriteRenderer != null)
            originalColor = spriteRenderer.color;
    }

    protected override void ExecuteBehavior()
    {
        // Base left movement
        transform.Translate(Vector3.left * moveSpeed * Time.deltaTime);

        // Handle growth based on distance to bird
        UpdateGrowth();
    }

    private void UpdateGrowth()
    {
        float distanceToBird = GetDistanceToBird();

        if (distanceToBird <= growStartDistance && birdTransform != null)
        {
            isGrowing = true;

            // Calculate target scale based on distance (closer = bigger)
            float distanceRatio = 1f - (distanceToBird / growStartDistance);
            float targetMultiplier = 1f + (maxScaleMultiplier - 1f) * distanceRatio;

            // Smoothly interpolate to target scale
            currentScaleMultiplier = Mathf.Lerp(currentScaleMultiplier, targetMultiplier, growSpeed * Time.deltaTime);

            // Check if fully grown
            isFullyGrown = currentScaleMultiplier >= maxScaleMultiplier * 0.95f;

            // Apply scale with optional pulse
            float finalMultiplier = currentScaleMultiplier;
            if (isFullyGrown && enablePulse)
            {
                finalMultiplier += Mathf.Sin(Time.time * pulseSpeed) * pulseIntensity;
            }

            transform.localScale = initialScale * finalMultiplier;

            // Update color based on growth
            if (spriteRenderer != null)
            {
                spriteRenderer.color = Color.Lerp(originalColor, growColor, distanceRatio);
            }
        }
        else if (isGrowing)
        {
            // Shrink back when bird moves away
            currentScaleMultiplier = Mathf.Lerp(currentScaleMultiplier, 1f, growSpeed * 0.5f * Time.deltaTime);
            transform.localScale = initialScale * currentScaleMultiplier;

            if (spriteRenderer != null)
            {
                spriteRenderer.color = Color.Lerp(spriteRenderer.color, originalColor, growSpeed * 0.5f * Time.deltaTime);
            }

            // Reset growing state when back to normal
            if (currentScaleMultiplier <= 1.05f)
            {
                isGrowing = false;
                isFullyGrown = false;
                currentScaleMultiplier = 1f;
                transform.localScale = initialScale;

                if (spriteRenderer != null)
                    spriteRenderer.color = originalColor;
            }
        }
    }

    protected override void OnHitBird(Bird bird)
    {
        // Calculate total damage (base + bonus if grown)
        int totalDamage = damage;

        if (isGrowing && currentScaleMultiplier > 1.2f)
        {
            totalDamage += explosionBonusDamage;
        }

        // Deal damage
        for (int i = 0; i < totalDamage; i++)
        {
            bird.GetHit();
        }

        DestroySelf();
    }

    /// <summary>
    /// Check if enemy is currently in growing state
    /// </summary>
    public bool IsGrowing()
    {
        return isGrowing;
    }

    /// <summary>
    /// Get current scale multiplier
    /// </summary>
    public float GetCurrentScaleMultiplier()
    {
        return currentScaleMultiplier;
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.red;
        Gizmos.DrawWireSphere(transform.position, growStartDistance);
    }
#endif
}

using UnityEngine;

/// <summary>
/// Enemy that splits into two smaller enemies when killed.
/// Creates a challenging scenario where destroying one enemy creates two more.
/// </summary>
public class SplitEnemy : BaseEnemy
{
    [Header("Split Settings")]
    [Tooltip("Prefab to spawn when split (if null, spawns copies of self)")]
    [SerializeField] private GameObject splitPrefab;

    [Tooltip("Number of enemies to spawn on split")]
    [SerializeField] private int splitCount = 2;

    [Tooltip("Scale multiplier for split enemies")]
    [SerializeField] private float splitScaleMultiplier = 0.6f;

    [Tooltip("Speed multiplier for split enemies")]
    [SerializeField] private float splitSpeedMultiplier = 1.2f;

    [Tooltip("Vertical spread when splitting")]
    [SerializeField] private float splitSpread = 1.5f;

    [Tooltip("Horizontal offset for split enemies")]
    [SerializeField] private float splitHorizontalOffset = 0.5f;

    [Header("Split Limits")]
    [Tooltip("Current generation (0 = original, increases with each split)")]
    [SerializeField] private int generation = 0;

    [Tooltip("Maximum generations allowed (prevents infinite splitting)")]
    [SerializeField] private int maxGenerations = 2;

    [Header("Visual Feedback")]
    [Tooltip("Color tint based on generation")]
    [SerializeField] private Color[] generationColors = new Color[]
    {
        Color.white,
        new Color(0.8f, 1f, 0.8f, 1f),
        new Color(0.6f, 1f, 0.6f, 1f)
    };

    public override EnemyType GetEnemyType() => EnemyType.Split;

    protected override void Start()
    {
        base.Start();
        ApplyGenerationVisuals();
    }

    protected override void ExecuteBehavior()
    {
        // Simple left movement
        transform.Translate(Vector3.left * moveSpeed * Time.deltaTime);
    }

    protected override void OnHitBird(Bird bird)
    {
        // Deal damage first
        for (int i = 0; i < damage; i++)
        {
            bird.GetHit();
        }

        // Then split (if allowed)
        if (generation < maxGenerations)
        {
            Split();
        }

        DestroySelf();
    }

    public override void Kill()
    {
        if (!isActive) return;

        isActive = false;

        // Split when killed (if allowed)
        if (generation < maxGenerations)
        {
            Split();
        }

        OnEnemyKilled?.Invoke(this);
        DestroySelf();
    }

    private void Split()
    {
        // Calculate spawn positions
        float angleStep = 180f / (splitCount + 1);

        for (int i = 0; i < splitCount; i++)
        {
            // Calculate spread position
            float angle = angleStep * (i + 1);
            float yOffset = Mathf.Sin(angle * Mathf.Deg2Rad) * splitSpread;

            // Alternate above and below
            if (i % 2 == 0)
                yOffset = splitSpread * 0.5f * (i + 1) / splitCount;
            else
                yOffset = -splitSpread * 0.5f * (i + 1) / splitCount;

            Vector3 spawnPos = transform.position + new Vector3(splitHorizontalOffset, yOffset, 0f);

            // Spawn the split enemy
            GameObject splitEnemy = SpawnSplitEnemy(spawnPos);

            if (splitEnemy != null)
            {
                ConfigureSplitEnemy(splitEnemy);
            }
        }
    }

    private GameObject SpawnSplitEnemy(Vector3 position)
    {
        GameObject prefabToSpawn = splitPrefab != null ? splitPrefab : gameObject;

        // If using self as prefab, we need to instantiate before destroying
        if (splitPrefab == null)
        {
            // Create a copy with the same setup
            GameObject copy = Instantiate(gameObject, position, Quaternion.identity);
            return copy;
        }
        else
        {
            return Instantiate(splitPrefab, position, Quaternion.identity);
        }
    }

    private void ConfigureSplitEnemy(GameObject enemyObj)
    {
        // Scale down
        enemyObj.transform.localScale = transform.localScale * splitScaleMultiplier;

        // Configure the enemy component
        if (enemyObj.TryGetComponent<SplitEnemy>(out var splitEnemy))
        {
            splitEnemy.generation = this.generation + 1;
            splitEnemy.moveSpeed = this.moveSpeed * splitSpeedMultiplier;
            splitEnemy.birdTransform = this.birdTransform;
            splitEnemy.destroyX = this.destroyX;
            splitEnemy.maxGenerations = this.maxGenerations;
            splitEnemy.splitPrefab = this.splitPrefab;
            splitEnemy.splitCount = this.splitCount;
            splitEnemy.splitScaleMultiplier = this.splitScaleMultiplier;
            splitEnemy.splitSpeedMultiplier = this.splitSpeedMultiplier;
            splitEnemy.ApplyGenerationVisuals();
        }
        else if (enemyObj.TryGetComponent<BaseEnemy>(out var baseEnemy))
        {
            // If split prefab is a different enemy type
            baseEnemy.Initialize(moveSpeed * splitSpeedMultiplier, birdTransform, destroyX);
        }
    }

    private void ApplyGenerationVisuals()
    {
        if (spriteRenderer != null && generation < generationColors.Length)
        {
            spriteRenderer.color = generationColors[generation];
        }
    }

    /// <summary>
    /// Set the generation level
    /// </summary>
    public void SetGeneration(int gen)
    {
        generation = gen;
        ApplyGenerationVisuals();
    }

    /// <summary>
    /// Get current generation
    /// </summary>
    public int GetGeneration()
    {
        return generation;
    }

    /// <summary>
    /// Check if this enemy can still split
    /// </summary>
    public bool CanSplit()
    {
        return generation < maxGenerations;
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.green;

        // Show split positions
        float angleStep = 180f / (splitCount + 1);
        for (int i = 0; i < splitCount; i++)
        {
            float yOffset = (i % 2 == 0) 
                ? splitSpread * 0.5f * (i + 1) / splitCount 
                : -splitSpread * 0.5f * (i + 1) / splitCount;

            Vector3 pos = transform.position + new Vector3(splitHorizontalOffset, yOffset, 0f);
            Gizmos.DrawWireSphere(pos, 0.3f);
        }
    }
#endif
}

using UnityEngine;

/// <summary>
/// Enemy that moves in a sinusoidal/circular pattern while traveling left.
/// Creates unpredictable movement that's harder to avoid.
/// </summary>
public class RotateEnemy : BaseEnemy
{
    [Header("Movement Pattern")]
    [Tooltip("Type of movement pattern")]
    [SerializeField] private MovementPattern pattern = MovementPattern.Sine;

    [Tooltip("Amplitude of the wave/circle movement")]
    [SerializeField] private float amplitude = 2f;

    [Tooltip("Frequency of the wave/rotation")]
    [SerializeField] private float frequency = 2f;

    [Tooltip("Phase offset for variation between enemies")]
    [SerializeField] private float phaseOffset = 0f;

    [Header("Rotation Visual")]
    [Tooltip("Rotate the sprite to match movement direction")]
    [SerializeField] private bool rotateSprite = true;

    [Tooltip("Additional constant rotation speed")]
    [SerializeField] private float constantRotationSpeed = 0f;

    [Header("Randomization")]
    [Tooltip("Randomize phase on start")]
    [SerializeField] private bool randomizePhase = true;

    [Tooltip("Randomize amplitude slightly")]
    [SerializeField] private bool randomizeAmplitude = false;

    [Tooltip("Amplitude variation range")]
    [SerializeField] private float amplitudeVariation = 0.5f;

    private float startY;
    private float timeOffset;
    private float actualAmplitude;
    private Vector3 lastPosition;

    public enum MovementPattern
    {
        Sine,           // Up and down sine wave
        Cosine,         // Cosine wave (starts at peak)
        Circle,         // Circular motion
        Figure8,        // Figure-8 pattern
        Zigzag          // Sharp zigzag pattern
    }

    public override EnemyType GetEnemyType() => EnemyType.Rotate;

    protected override void Start()
    {
        base.Start();

        startY = transform.position.y;
        lastPosition = transform.position;

        // Apply randomization
        if (randomizePhase)
            phaseOffset = Random.Range(0f, Mathf.PI * 2f);

        actualAmplitude = amplitude;
        if (randomizeAmplitude)
            actualAmplitude = amplitude + Random.Range(-amplitudeVariation, amplitudeVariation);

        timeOffset = Time.time;
    }

    protected override void ExecuteBehavior()
    {
        float elapsed = Time.time - timeOffset;
        float t = elapsed * frequency + phaseOffset;

        // Calculate new position based on pattern
        Vector3 newPosition = CalculatePosition(t);

        // Apply constant rotation if enabled
        if (constantRotationSpeed != 0f)
        {
            transform.Rotate(0f, 0f, constantRotationSpeed * Time.deltaTime);
        }

        // Rotate sprite to face movement direction
        if (rotateSprite && spriteRenderer != null)
        {
            Vector3 direction = newPosition - lastPosition;
            if (direction.sqrMagnitude > 0.0001f)
            {
                float angle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg;
                spriteRenderer.transform.rotation = Quaternion.Euler(0f, 0f, angle);
            }
        }

        lastPosition = transform.position;
        transform.position = newPosition;
    }

    private Vector3 CalculatePosition(float t)
    {
        float x = transform.position.x - moveSpeed * Time.deltaTime;
        float y = startY;

        switch (pattern)
        {
            case MovementPattern.Sine:
                y = startY + Mathf.Sin(t) * actualAmplitude;
                break;

            case MovementPattern.Cosine:
                y = startY + Mathf.Cos(t) * actualAmplitude;
                break;

            case MovementPattern.Circle:
                // Circular motion - both X and Y affected
                float circleX = Mathf.Cos(t) * actualAmplitude * 0.5f;
                x = transform.position.x - moveSpeed * Time.deltaTime + circleX * Time.deltaTime * frequency;
                y = startY + Mathf.Sin(t) * actualAmplitude;
                break;

            case MovementPattern.Figure8:
                // Figure-8 (Lissajous curve)
                y = startY + Mathf.Sin(t) * actualAmplitude;
                float figure8X = Mathf.Sin(t * 2f) * actualAmplitude * 0.3f;
                x = transform.position.x - moveSpeed * Time.deltaTime + figure8X * Time.deltaTime;
                break;

            case MovementPattern.Zigzag:
                // Sharp zigzag using triangle wave
                float triangleWave = Mathf.Abs((t % (Mathf.PI * 2f)) / Mathf.PI - 1f) * 2f - 1f;
                y = startY + triangleWave * actualAmplitude;
                break;
        }

        return new Vector3(x, y, transform.position.z);
    }

    /// <summary>
    /// Set the movement pattern at runtime
    /// </summary>
    public void SetPattern(MovementPattern newPattern)
    {
        pattern = newPattern;
    }

    /// <summary>
    /// Set amplitude at runtime
    /// </summary>
    public void SetAmplitude(float newAmplitude)
    {
        amplitude = newAmplitude;
        actualAmplitude = newAmplitude;
    }

    /// <summary>
    /// Set frequency at runtime
    /// </summary>
    public void SetFrequency(float newFrequency)
    {
        frequency = newFrequency;
    }

    /// <summary>
    /// Get current movement pattern
    /// </summary>
    public MovementPattern GetPattern()
    {
        return pattern;
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.cyan;

        // Preview the movement path
        Vector3 previewStart = Application.isPlaying ? new Vector3(transform.position.x, startY, 0f) : transform.position;
        Vector3 lastPos = previewStart;

        float previewAmplitude = Application.isPlaying ? actualAmplitude : amplitude;

        for (int i = 1; i <= 50; i++)
        {
            float t = i * 0.2f + phaseOffset;
            float y = 0f;
            float xOffset = 0f;

            switch (pattern)
            {
                case MovementPattern.Sine:
                    y = Mathf.Sin(t) * previewAmplitude;
                    break;
                case MovementPattern.Cosine:
                    y = Mathf.Cos(t) * previewAmplitude;
                    break;
                case MovementPattern.Circle:
                    y = Mathf.Sin(t) * previewAmplitude;
                    xOffset = Mathf.Cos(t) * previewAmplitude * 0.3f;
                    break;
                case MovementPattern.Figure8:
                    y = Mathf.Sin(t) * previewAmplitude;
                    xOffset = Mathf.Sin(t * 2f) * previewAmplitude * 0.3f;
                    break;
                case MovementPattern.Zigzag:
                    float triangleWave = Mathf.Abs((t % (Mathf.PI * 2f)) / Mathf.PI - 1f) * 2f - 1f;
                    y = triangleWave * previewAmplitude;
                    break;
            }

            Vector3 pos = previewStart + new Vector3(-i * 0.3f + xOffset, y, 0f);
            Gizmos.DrawLine(lastPos, pos);
            lastPos = pos;
        }
    }
#endif
}

using UnityEngine;

/// <summary>
/// Configuration for enemy spawning - defines which enemies can spawn and their weights.
/// Attach to EnemySpawner or use as ScriptableObject for different difficulty levels.
/// </summary>
[System.Serializable]
public class EnemySpawnEntry
{
    [Tooltip("The enemy prefab to spawn")]
    public GameObject enemyPrefab;

    [Tooltip("Spawn weight (higher = more likely to spawn)")]
    [Range(0f, 100f)]
    public float spawnWeight = 1f;

    [Tooltip("Minimum level required for this enemy to spawn")]
    public int minLevel = 1;

    [Tooltip("Maximum level for this enemy (0 = no limit)")]
    public int maxLevel = 0;

    [Tooltip("Speed multiplier for this enemy type")]
    public float speedMultiplier = 1f;

    /// <summary>
    /// Check if this enemy can spawn at the given level
    /// </summary>
    public bool CanSpawnAtLevel(int level)
    {
        if (level < minLevel) return false;
        if (maxLevel > 0 && level > maxLevel) return false;
        return true;
    }
}

/// <summary>
/// ScriptableObject for storing enemy spawn configurations.
/// Create different configs for different difficulty levels or game modes.
/// </summary>
[CreateAssetMenu(fileName = "EnemySpawnConfig", menuName = "Game/Enemy Spawn Config")]
public class EnemySpawnConfig : ScriptableObject
{
    [Header("Spawn Entries")]
    [Tooltip("List of enemies that can be spawned")]
    public EnemySpawnEntry[] enemies;

    [Header("Level Scaling")]
    [Tooltip("Base spawn interval in seconds")]
    public float baseSpawnInterval = 3f;

    [Tooltip("Minimum spawn interval")]
    public float minSpawnInterval = 1f;

    [Tooltip("Spawn interval reduction per level")]
    public float intervalReductionPerLevel = 0.1f;

    [Header("Speed Scaling")]
    [Tooltip("Base enemy speed")]
    public float baseSpeed = 3f;

    [Tooltip("Speed increase per level")]
    public float speedIncreasePerLevel = 0.2f;

    [Tooltip("Maximum speed cap")]
    public float maxSpeed = 8f;

    /// <summary>
    /// Get spawn interval for a specific level
    /// </summary>
    public float GetSpawnInterval(int level)
    {
        float interval = baseSpawnInterval - (level - 1) * intervalReductionPerLevel;
        return Mathf.Max(interval, minSpawnInterval);
    }

    /// <summary>
    /// Get enemy speed for a specific level
    /// </summary>
    public float GetEnemySpeed(int level)
    {
        float speed = baseSpeed + (level - 1) * speedIncreasePerLevel;
        return Mathf.Min(speed, maxSpeed);
    }

    /// <summary>
    /// Get a random enemy that can spawn at the given level
    /// </summary>
    public EnemySpawnEntry GetRandomEnemy(int level)
    {
        // Calculate total weight of available enemies
        float totalWeight = 0f;
        foreach (var entry in enemies)
        {
            if (entry.CanSpawnAtLevel(level) && entry.enemyPrefab != null)
            {
                totalWeight += entry.spawnWeight;
            }
        }

        if (totalWeight <= 0f) return null;

        // Random selection based on weight
        float random = Random.Range(0f, totalWeight);
        float currentWeight = 0f;

        foreach (var entry in enemies)
        {
            if (entry.CanSpawnAtLevel(level) && entry.enemyPrefab != null)
            {
                currentWeight += entry.spawnWeight;
                if (random <= currentWeight)
                {
                    return entry;
                }
            }
        }

        return null;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Spawns enemies based on configuration and current level.
/// Supports random enemy selection with weighted probabilities and difficulty scaling.
/// </summary>
public class EnemySpawner : MonoBehaviour
{
    [Header("Spawn Configuration")]
    [Tooltip("ScriptableObject config (optional - can use inline entries instead)")]
    [SerializeField] private EnemySpawnConfig spawnConfig;

    [Tooltip("Inline enemy entries (used if no ScriptableObject config)")]
    [SerializeField] private EnemySpawnEntry[] inlineEnemies;

    [Header("Spawn Settings")]
    [Tooltip("Base spawn interval in seconds")]
    [SerializeField] private float baseSpawnInterval = 3f;

    [Tooltip("Minimum spawn interval")]
    [SerializeField] private float minSpawnInterval = 1f;

    [Tooltip("Interval reduction per level")]
    [SerializeField] private float intervalReductionPerLevel = 0.1f;

    [Header("Position Settings")]
    [Tooltip("Spawn X position (right side of screen)")]
    [SerializeField] private float spawnX = 15f;

    [Tooltip("Minimum Y position for spawning")]
    [SerializeField] private float minY = -4f;

    [Tooltip("Maximum Y position for spawning")]
    [SerializeField] private float maxY = 4f;

    [Tooltip("X position where enemies are destroyed")]
    [SerializeField] private float destroyX = -15f;

    [Header("Speed Settings")]
    [Tooltip("Base enemy movement speed")]
    [SerializeField] private float baseSpeed = 3f;

    [Tooltip("Speed increase per level")]
    [SerializeField] private float speedIncreasePerLevel = 0.2f;

    [Tooltip("Maximum enemy speed")]
    [SerializeField] private float maxSpeed = 8f;

    [Header("References")]
    [Tooltip("Reference to the bird (auto-found if null)")]
    [SerializeField] private Transform birdTransform;

    // Runtime state
    private int currentLevel = 1;
    private bool isSpawning = false;
    private Coroutine spawnCoroutine;
    private List<BaseEnemy> activeEnemies = new List<BaseEnemy>();

    // Events
    public System.Action<BaseEnemy> OnEnemySpawned;
    public System.Action<BaseEnemy> OnEnemyDestroyed;

    #region Unity Lifecycle

    private void Awake()
    {
        // Auto-find bird if not assigned
        if (birdTransform == null)
        {
            var bird = FindFirstObjectByType<Bird>();
            if (bird != null)
                birdTransform = bird.transform;
        }
    }

    private void OnDestroy()
    {
        StopSpawning();
    }

    #endregion

    #region Public Methods

    /// <summary>
    /// Initialize the spawner with level settings
    /// </summary>
    public void Initialize(int level)
    {
        currentLevel = level;
    }

    /// <summary>
    /// Start spawning enemies
    /// </summary>
    public void StartSpawning()
    {
        if (isSpawning) return;

        isSpawning = true;
        spawnCoroutine = StartCoroutine(SpawnRoutine());
    }

    /// <summary>
    /// Stop spawning enemies
    /// </summary>
    public void StopSpawning()
    {
        isSpawning = false;

        if (spawnCoroutine != null)
        {
            StopCoroutine(spawnCoroutine);
            spawnCoroutine = null;
        }
    }

    /// <summary>
    /// Stop spawning and destroy all active enemies
    /// </summary>
    public void StopAndClearAll()
    {
        StopSpawning();
        DestroyAllEnemies();
    }

    /// <summary>
    /// Destroy all active enemies
    /// </summary>
    public void DestroyAllEnemies()
    {
        for (int i = activeEnemies.Count - 1; i >= 0; i--)
        {
            if (activeEnemies[i] != null)
            {
                Destroy(activeEnemies[i].gameObject);
            }
        }
        activeEnemies.Clear();
    }

    /// <summary>
    /// Pause all active enemies
    /// </summary>
    public void PauseAllEnemies()
    {
        foreach (var enemy in activeEnemies)
        {
            if (enemy != null)
                enemy.SetActive(false);
        }
    }

    /// <summary>
    /// Resume all active enemies
    /// </summary>
    public void ResumeAllEnemies()
    {
        foreach (var enemy in activeEnemies)
        {
            if (enemy != null)
                enemy.SetActive(true);
        }
    }

    /// <summary>
    /// Spawn a specific enemy type at a position
    /// </summary>
    public BaseEnemy SpawnEnemy(GameObject prefab, Vector3 position)
    {
        if (prefab == null) return null;

        GameObject enemyObj = Instantiate(prefab, position, Quaternion.identity);
        BaseEnemy enemy = enemyObj.GetComponent<BaseEnemy>();

        if (enemy != null)
        {
            ConfigureEnemy(enemy, 1f);
            RegisterEnemy(enemy);
        }

        return enemy;
    }

    /// <summary>
    /// Spawn a random enemy based on current level
    /// </summary>
    public BaseEnemy SpawnRandomEnemy()
    {
        EnemySpawnEntry entry = GetRandomEnemyEntry();
        if (entry == null || entry.enemyPrefab == null) return null;

        Vector3 spawnPos = GetRandomSpawnPosition();
        GameObject enemyObj = Instantiate(entry.enemyPrefab, spawnPos, Quaternion.identity);
        BaseEnemy enemy = enemyObj.GetComponent<BaseEnemy>();

        if (enemy != null)
        {
            ConfigureEnemy(enemy, entry.speedMultiplier);
            RegisterEnemy(enemy);
        }

        return enemy;
    }

    /// <summary>
    /// Set the current level for difficulty scaling
    /// </summary>
    public void SetLevel(int level)
    {
        currentLevel = Mathf.Max(1, level);
    }

    /// <summary>
    /// Get count of active enemies
    /// </summary>
    public int GetActiveEnemyCount()
    {
        // Clean up null references
        activeEnemies.RemoveAll(e => e == null);
        return activeEnemies.Count;
    }

    /// <summary>
    /// Get all active enemies
    /// </summary>
    public List<BaseEnemy> GetActiveEnemies()
    {
        activeEnemies.RemoveAll(e => e == null);
        return new List<BaseEnemy>(activeEnemies);
    }

    #endregion

    #region Private Methods

    private IEnumerator SpawnRoutine()
    {
        while (isSpawning)
        {
            float interval = GetSpawnInterval();
            yield return new WaitForSeconds(interval);

            if (isSpawning)
            {
                SpawnRandomEnemy();
            }
        }
    }

    private EnemySpawnEntry GetRandomEnemyEntry()
    {
        // Use ScriptableObject config if available
        if (spawnConfig != null)
        {
            return spawnConfig.GetRandomEnemy(currentLevel);
        }

        // Otherwise use inline entries
        if (inlineEnemies == null || inlineEnemies.Length == 0)
            return null;

        // Calculate total weight
        float totalWeight = 0f;
        foreach (var entry in inlineEnemies)
        {
            if (entry.CanSpawnAtLevel(currentLevel) && entry.enemyPrefab != null)
            {
                totalWeight += entry.spawnWeight;
            }
        }

        if (totalWeight <= 0f) return null;

        // Random selection
        float random = Random.Range(0f, totalWeight);
        float currentWeight = 0f;

        foreach (var entry in inlineEnemies)
        {
            if (entry.CanSpawnAtLevel(currentLevel) && entry.enemyPrefab != null)
            {
                currentWeight += entry.spawnWeight;
                if (random <= currentWeight)
                {
                    return entry;
                }
            }
        }

        return null;
    }

    private Vector3 GetRandomSpawnPosition()
    {
        float y = Random.Range(minY, maxY);
        return new Vector3(spawnX, y, 0f);
    }

    private void ConfigureEnemy(BaseEnemy enemy, float speedMultiplier)
    {
        float speed = GetEnemySpeed() * speedMultiplier;
        enemy.Initialize(speed, birdTransform, destroyX);
    }

    private void RegisterEnemy(BaseEnemy enemy)
    {
        activeEnemies.Add(enemy);

        // Subscribe to destruction event
        enemy.OnEnemyDestroyed += HandleEnemyDestroyed;

        OnEnemySpawned?.Invoke(enemy);
    }

    private void HandleEnemyDestroyed(BaseEnemy enemy)
    {
        activeEnemies.Remove(enemy);
        enemy.OnEnemyDestroyed -= HandleEnemyDestroyed;
        OnEnemyDestroyed?.Invoke(enemy);
    }

    private float GetSpawnInterval()
    {
        if (spawnConfig != null)
        {
            return spawnConfig.GetSpawnInterval(currentLevel);
        }

        float interval = baseSpawnInterval - (currentLevel - 1) * intervalReductionPerLevel;
        return Mathf.Max(interval, minSpawnInterval);
    }

    private float GetEnemySpeed()
    {
        if (spawnConfig != null)
        {
            return spawnConfig.GetEnemySpeed(currentLevel);
        }

        float speed = baseSpeed + (currentLevel - 1) * speedIncreasePerLevel;
        return Mathf.Min(speed, maxSpeed);
    }

    #endregion

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        // Draw spawn area
        Gizmos.color = Color.green;
        Vector3 topRight = new Vector3(spawnX, maxY, 0f);
        Vector3 bottomRight = new Vector3(spawnX, minY, 0f);
        Gizmos.DrawLine(topRight, bottomRight);
        Gizmos.DrawWireSphere(topRight, 0.3f);
        Gizmos.DrawWireSphere(bottomRight, 0.3f);

        // Draw destroy line
        Gizmos.color = Color.red;
        Vector3 topLeft = new Vector3(destroyX, maxY, 0f);
        Vector3 bottomLeft = new Vector3(destroyX, minY, 0f);
        Gizmos.DrawLine(topLeft, bottomLeft);
    }
#endif
}

