/// <summary>
/// Central manager for the enemy system.
/// Coordinates spawning, tracks active enemies, and handles game state changes.
/// </summary>
public class EnemyManager : MonoBehaviour
{
    [Header("References")]
    [Tooltip("Reference to the enemy spawner")]
    [SerializeField] private EnemySpawner enemySpawner;

    [Tooltip("Reference to the game director (optional)")]
    [SerializeField] private GameDirector gameDirector;

    [Header("Settings")]
    [Tooltip("Auto-start spawning on game start")]
    [SerializeField] private bool autoStart = false;

    // Statistics
    private int totalEnemiesSpawned = 0;
    private int totalEnemiesKilled = 0;
    private int totalEnemiesEscaped = 0;

    // Events
    public System.Action<int> OnEnemyCountChanged;
    public System.Action<BaseEnemy> OnEnemySpawned;
    public System.Action<BaseEnemy> OnEnemyKilled;

    #region Unity Lifecycle

    private void Awake()
    {
        // Auto-find spawner if not assigned
        if (enemySpawner == null)
            enemySpawner = GetComponentInChildren<EnemySpawner>();

        // Auto-find game director if not assigned
        if (gameDirector == null)
            gameDirector = FindFirstObjectByType<GameDirector>();
    }

    private void Start()
    {
        if (enemySpawner != null)
        {
            // Subscribe to spawner events
            enemySpawner.OnEnemySpawned += HandleEnemySpawned;
            enemySpawner.OnEnemyDestroyed += HandleEnemyDestroyed;
        }

        if (autoStart)
        {
            StartEnemySystem();
        }
    }

    private void OnDestroy()
    {
        if (enemySpawner != null)
        {
            enemySpawner.OnEnemySpawned -= HandleEnemySpawned;
            enemySpawner.OnEnemyDestroyed -= HandleEnemyDestroyed;
        }
    }

    #endregion

    #region Public Methods

    /// <summary>
    /// Initialize and start the enemy system for a level
    /// </summary>
    public void StartEnemySystem()
    {
        if (enemySpawner == null)
        {
            Debug.LogWarning("EnemyManager: No EnemySpawner assigned!");
            return;
        }

        int level = gameDirector != null ? gameDirector.currentLevel : 1;
        enemySpawner.Initialize(level);
        enemySpawner.StartSpawning();
    }

    /// <summary>
    /// Stop the enemy system
    /// </summary>
    public void StopEnemySystem()
    {
        if (enemySpawner != null)
        {
            enemySpawner.StopSpawning();
        }
    }

    /// <summary>
    /// Stop and clear all enemies
    /// </summary>
    public void ResetEnemySystem()
    {
        if (enemySpawner != null)
        {
            enemySpawner.StopAndClearAll();
        }

        ResetStatistics();
    }

    /// <summary>
    /// Pause all enemy movement
    /// </summary>
    public void PauseEnemies()
    {
        if (enemySpawner != null)
        {
            enemySpawner.PauseAllEnemies();
        }
    }

    /// <summary>
    /// Resume all enemy movement
    /// </summary>
    public void ResumeEnemies()
    {
        if (enemySpawner != null)
        {
            enemySpawner.ResumeAllEnemies();
        }
    }

    /// <summary>
    /// Set the current level for difficulty scaling
    /// </summary>
    public void SetLevel(int level)
    {
        if (enemySpawner != null)
        {
            enemySpawner.SetLevel(level);
        }
    }

    /// <summary>
    /// Get count of currently active enemies
    /// </summary>
    public int GetActiveEnemyCount()
    {
        return enemySpawner != null ? enemySpawner.GetActiveEnemyCount() : 0;
    }

    /// <summary>
    /// Get all active enemies
    /// </summary>
    public List<BaseEnemy> GetActiveEnemies()
    {
        return enemySpawner != null ? enemySpawner.GetActiveEnemies() : new List<BaseEnemy>();
    }

    /// <summary>
    /// Spawn a specific enemy at a position
    /// </summary>
    public BaseEnemy SpawnEnemy(GameObject prefab, Vector3 position)
    {
        return enemySpawner != null ? enemySpawner.SpawnEnemy(prefab, position) : null;
    }

    /// <summary>
    /// Kill all active enemies (for power-ups, etc.)
    /// </summary>
    public void KillAllEnemies()
    {
        if (enemySpawner == null) return;

        var enemies = enemySpawner.GetActiveEnemies();
        foreach (var enemy in enemies)
        {
            if (enemy != null)
            {
                enemy.Kill();
            }
        }
    }

    #endregion

    #region Statistics

    /// <summary>
    /// Get total enemies spawned this session
    /// </summary>
    public int GetTotalSpawned() => totalEnemiesSpawned;

    /// <summary>
    /// Get total enemies killed this session
    /// </summary>
    public int GetTotalKilled() => totalEnemiesKilled;

    /// <summary>
    /// Get total enemies that escaped (went off-screen)
    /// </summary>
    public int GetTotalEscaped() => totalEnemiesEscaped;

    /// <summary>
    /// Reset all statistics
    /// </summary>
    public void ResetStatistics()
    {
        totalEnemiesSpawned = 0;
        totalEnemiesKilled = 0;
        totalEnemiesEscaped = 0;
    }

    #endregion

    #region Event Handlers

    private void HandleEnemySpawned(BaseEnemy enemy)
    {
        totalEnemiesSpawned++;

        // Subscribe to kill event
        enemy.OnEnemyKilled += HandleEnemyKilled;

        OnEnemySpawned?.Invoke(enemy);
        OnEnemyCountChanged?.Invoke(GetActiveEnemyCount());
    }

    private void HandleEnemyDestroyed(BaseEnemy enemy)
    {
        // Check if it was killed or escaped
        // (If killed, OnEnemyKilled would have been called first)

        OnEnemyCountChanged?.Invoke(GetActiveEnemyCount());
    }

    private void HandleEnemyKilled(BaseEnemy enemy)
    {
        totalEnemiesKilled++;
        enemy.OnEnemyKilled -= HandleEnemyKilled;
        OnEnemyKilled?.Invoke(enemy);
    }

    #endregion
}

using UnityEngine;
using UnityEditor;

public class SetupEnemySystem : MonoBehaviour
{
    [MenuItem("Tools/Setup Enemy System")]
    public static void Execute()
    {
        // Setup SplitEnemy prefab to reference itself
        string splitEnemyPath = "Assets/Prefabs/Enemies/SplitEnemy.prefab";
        GameObject splitPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(splitEnemyPath);

        if (splitPrefab != null)
        {
            // Open prefab for editing
            string assetPath = AssetDatabase.GetAssetPath(splitPrefab);
            GameObject prefabRoot = PrefabUtility.LoadPrefabContents(assetPath);

            SplitEnemy splitEnemy = prefabRoot.GetComponent<SplitEnemy>();
            if (splitEnemy != null)
            {
                // Use SerializedObject to set the splitPrefab field
                SerializedObject so = new SerializedObject(splitEnemy);
                SerializedProperty splitPrefabProp = so.FindProperty("splitPrefab");
                if (splitPrefabProp != null)
                {
                    splitPrefabProp.objectReferenceValue = splitPrefab;
                    so.ApplyModifiedProperties();
                }
            }

            // Save prefab
            PrefabUtility.SaveAsPrefabAsset(prefabRoot, assetPath);
            PrefabUtility.UnloadPrefabContents(prefabRoot);

            Debug.Log("SplitEnemy prefab configured with self-reference.");
        }

        // Setup EnemySpawner with enemy prefabs
        EnemySpawner spawner = FindFirstObjectByType<EnemySpawner>();
        if (spawner != null)
        {
            SerializedObject spawnerSO = new SerializedObject(spawner);
            SerializedProperty inlineEnemies = spawnerSO.FindProperty("inlineEnemies");

            // Load all enemy prefabs
            GameObject normalPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Enemies/NormalEnemy.prefab");
            GameObject followPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Enemies/FollowEnemy.prefab");
            GameObject explodePrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Enemies/ExplodeEnemy.prefab");
            GameObject rotatePrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Enemies/RotateEnemy.prefab");

            // Clear and setup inline enemies
            inlineEnemies.ClearArray();

            // Add NormalEnemy - Level 1+, high weight
            AddEnemyEntry(inlineEnemies, normalPrefab, 50f, 1, 0, 1f);

            // Add FollowEnemy - Level 2+, medium weight
            AddEnemyEntry(inlineEnemies, followPrefab, 30f, 2, 0, 0.9f);

            // Add RotateEnemy - Level 2+, medium weight
            AddEnemyEntry(inlineEnemies, rotatePrefab, 25f, 2, 0, 1f);

            // Add ExplodeEnemy - Level 3+, lower weight
            AddEnemyEntry(inlineEnemies, explodePrefab, 20f, 3, 0, 0.8f);

            // Add SplitEnemy - Level 4+, lowest weight (challenging)
            AddEnemyEntry(inlineEnemies, splitPrefab, 15f, 4, 0, 0.85f);

            spawnerSO.ApplyModifiedProperties();
            EditorUtility.SetDirty(spawner);

            Debug.Log("EnemySpawner configured with 5 enemy types.");
        }
        else
        {
            Debug.LogWarning("EnemySpawner not found in scene!");
        }

        Debug.Log("Enemy system setup complete!");
    }

    private static void AddEnemyEntry(SerializedProperty array, GameObject prefab, float weight, int minLevel, int maxLevel, float speedMult)
    {
        int index = array.arraySize;
        array.InsertArrayElementAtIndex(index);
        SerializedProperty element = array.GetArrayElementAtIndex(index);

        element.FindPropertyRelative("enemyPrefab").objectReferenceValue = prefab;
        element.FindPropertyRelative("spawnWeight").floatValue = weight;
        element.FindPropertyRelative("minLevel").intValue = minLevel;
        element.FindPropertyRelative("maxLevel").intValue = maxLevel;
        element.FindPropertyRelative("speedMultiplier").floatValue = speedMult;
    }
}

