using UnityEngine;
using UnityEditor;

public class SetupEnemyTags
{
    public static void Execute()
    {
        // Add Enemy tag if it doesn't exist
        SerializedObject tagManager = new SerializedObject(AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/TagManager.asset")[0]);
        SerializedProperty tagsProp = tagManager.FindProperty("tags");

        bool enemyTagExists = false;
        for (int i = 0; i < tagsProp.arraySize; i++)
        {
            if (tagsProp.GetArrayElementAtIndex(i).stringValue == "Enemy")
            {
                enemyTagExists = true;
                break;
            }
        }

        if (!enemyTagExists)
        {
            tagsProp.InsertArrayElementAtIndex(tagsProp.arraySize);
            tagsProp.GetArrayElementAtIndex(tagsProp.arraySize - 1).stringValue = "Enemy";
            tagManager.ApplyModifiedProperties();
            Debug.Log("Added 'Enemy' tag to TagManager.");
        }
        else
        {
            Debug.Log("'Enemy' tag already exists.");
        }

        // Set tag on all enemy prefabs
        string[] enemyPrefabPaths = new string[]
        {
            "Assets/Prefabs/Enemies/NormalEnemy.prefab",
            "Assets/Prefabs/Enemies/FollowEnemy.prefab",
            "Assets/Prefabs/Enemies/ExplodeEnemy.prefab",
            "Assets/Prefabs/Enemies/SplitEnemy.prefab",
            "Assets/Prefabs/Enemies/RotateEnemy.prefab"
        };

        foreach (string path in enemyPrefabPaths)
        {
            GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (prefab != null)
            {
                GameObject prefabRoot = PrefabUtility.LoadPrefabContents(path);
                prefabRoot.tag = "Enemy";
                PrefabUtility.SaveAsPrefabAsset(prefabRoot, path);
                PrefabUtility.UnloadPrefabContents(prefabRoot);
                Debug.Log($"Set 'Enemy' tag on {path}");
            }
        }

        Debug.Log("Enemy tags setup complete!");
    }
}

